render_block = '''function isBuilderFormat(f){return["sentence_builder","sentence_reorder","word_order","reorder"].indexOf(String(f||""))>=0}\nfunction validateQuestionContract(q){\n  if(!q||!q.id||!q.prompt)return false;var f=String(q.format||"");\n  if(f==="listening_choice"&&!q.audio_text)return false;\n  if(isBuilderFormat(f))return Array.isArray(q.tokens)&&q.tokens.length>=2;\n  if(["pronunciation_correction","voice_pronunciation","match_pairs","pair_match","matching"].indexOf(f)>=0)return false;\n  return Array.isArray(q.options)&&q.options.length>=2;\n}\nfunction renderQuestion(){\n  var q=RV.questions[RV.idx],n=RV.questions.length;if(!validateQuestionContract(q)){alert(L.err);closeReview();return}\n  RV.builder=[];RV.locked=false;\n  $("rv-fill").style.width=Math.round((RV.idx/n)*100)+"%";\n  var qcat=q.category?catLabel(q.category):L.q;\n  var audio=q.audio_text?'<button class="rv-audio" onclick="speakMistake(\\''+jsq(q.audio_text)+'\\')"><i class="ti ti-volume"></i></button>':'';\n  var sentence=q.sentence?'<div class="han">'+esc(q.sentence)+'</div>':'';\n  var pinyin=q.pinyin?'<div class="py">'+esc(q.pinyin)+'</div>':'';\n  var material=(audio||sentence||pinyin)?'<div class="rv-material">'+audio+sentence+pinyin+'</div>':'';\n  var interaction='';\n  if(isBuilderFormat(q.format)){\n    interaction='<div class="rv-builder-answer empty" id="rv-builder-answer" data-placeholder="'+esc(L.buildHint)+'"></div><div class="rv-builder-bank" id="rv-builder-bank"></div><div class="rv-builder-actions"><button onclick="builderUndo()">'+esc(L.undo)+'</button><button onclick="builderClear()">'+esc(L.clear)+'</button></div>';\n  }else{\n    interaction='<div class="rv-opts" id="rv-opts">'+q.options.map(function(o,i){return '<button class="rv-opt" data-i="'+i+'" onclick="pickOption('+i+')"><span class="rk">'+LETTERS(i)+'</span><span>'+esc(o)+'</span></button>'}).join("")+'</div>';\n  }\n  $("rv-body").innerHTML='<div class="rv-cat">'+esc(qcat)+' · '+L.q+' '+(RV.idx+1)+' '+L.of+' '+n+'</div><div class="rv-prompt">'+esc(q.prompt)+'</div>'+material+interaction+'<div id="rv-fb"></div>';\n  $("rv-foot").innerHTML=isBuilderFormat(q.format)?'<button id="rv-builder-submit" disabled onclick="submitBuilder()"><i class="ti ti-check"></i> '+esc(L.check)+'</button>':"";\n  if(isBuilderFormat(q.format))renderBuilderState();\n}\nfunction jsq'''
