builder_functions = '''\nfunction renderBuilderState(){\n  var q=RV.questions[RV.idx],answer=$("rv-builder-answer"),bank=$("rv-builder-bank");if(!answer||!bank)return;\n  var used={};RV.builder.forEach(function(x){used[x.i]=true});\n  answer.className="rv-builder-answer"+(RV.builder.length?"":" empty");\n  answer.innerHTML=RV.builder.map(function(x,p){return '<button class="rv-token answer" onclick="removeBuilderToken('+p+')">'+esc(x.v)+'</button>'}).join("");\n  bank.innerHTML=q.tokens.map(function(v,i){return '<button class="rv-token '+(used[i]?"used":"")+'" onclick="pickBuilderToken('+i+')">'+esc(v)+'</button>'}).join("");\n  var submit=$("rv-builder-submit");if(submit)submit.disabled=RV.builder.length!==q.tokens.length||!!RV.locked;\n}\nfunction pickBuilderToken(i){var q=RV.questions[RV.idx];if(RV.locked||!q||i<0||i>=q.tokens.length)return;if(RV.builder.some(function(x){return x.i===i}))return;RV.builder.push({i:i,v:q.tokens[i]});renderBuilderState()}\nfunction removeBuilderToken(p){if(RV.locked||p<0||p>=RV.builder.length)return;RV.builder.splice(p,1);renderBuilderState()}\nfunction builderUndo(){if(RV.locked||!RV.builder.length)return;RV.builder.pop();renderBuilderState()}\nfunction builderClear(){if(RV.locked)return;RV.builder=[];renderBuilderState()}\nfunction submitBuilder(){\n  var q=RV.questions[RV.idx];if(RV.locked||!q||RV.builder.length!==q.tokens.length)return;RV.locked=true;renderBuilderState();\n  var selected=RV.builder.map(function(x){return x.v});\n  fetch("/api/miniapp/mistakes/review/answer",{method:"POST",headers:{"X-Telegram-Init-Data":INIT_DATA,"Content-Type":"application/json"},body:JSON.stringify({session_id:RV.session,question_id:q.id,selected_index:selected})})\n  .then(function(r){return r.json()}).then(function(d){\n    if(!d||!d.ok||!Array.isArray(d.selected_tokens))throw new Error("answer_failed");\n    RV.answers.push({question_id:q.id,selected_tokens:d.selected_tokens});var correct=!!d.correct;haptic(correct?"success":"error");\n    var explanation=String(d.explanation||""),ex=explanation&&explanation!==String(d.correct_answer||"")?'<div class="ex">'+esc(explanation)+'</div>':"";\n    $("rv-fb").innerHTML='<div class="rv-fb '+(correct?"ok":"no")+'"><b><i class="ti ti-'+(correct?"circle-check":"alert-circle")+'"></i> '+(correct?L.correct:L.wrong)+'</b>'+(correct?"":'<div>'+L.exp+': '+esc(d.correct_answer||"")+'</div>')+ex+'</div>';\n    var last=RV.idx>=RV.questions.length-1;$("rv-foot").innerHTML='<button onclick="nextQuestion()">'+(last?'<i class="ti ti-check"></i> '+L.finish:L.next+' <i class="ti ti-arrow-right"></i>')+'</button>';\n  }).catch(function(){RV.locked=false;renderBuilderState();alert(L.err)});\n}\n'''
